use std::collections::{HashSet,HashMap,VecDeque};impl Solution{pub fn find_ladders(begin:String,end:String,words:Vec<String>)->Vec<Vec<String>>{let dict:HashSet<String>=words.into_iter().collect();if !dict.contains(&end){return vec![]}let mut dist:HashMap<String,i32>=HashMap::new();let mut pre:HashMap<String,Vec<String>>=HashMap::new();let mut q=VecDeque::new();dist.insert(begin.clone(),0);q.push_back(begin.clone());while let Some(w)=q.pop_front(){let nd=dist[&w]+1;let mut b=w.as_bytes().to_vec();for i in 0..b.len(){let old=b[i];for c in b'a'..=b'z'{b[i]=c;let x=String::from_utf8(b.clone()).unwrap();if dict.contains(&x){if !dist.contains_key(&x){dist.insert(x.clone(),nd);q.push_back(x.clone());}if dist[&x]==nd{pre.entry(x).or_default().push(w.clone());}}}b[i]=old;}}fn dfs(w:&str,b:&str,pre:&HashMap<String,Vec<String>>,p:&mut Vec<String>,o:&mut Vec<Vec<String>>){p.push(w.to_string());if w==b{let mut v=p.clone();v.reverse();o.push(v);}else if let Some(xs)=pre.get(w){for x in xs{dfs(x,b,pre,p,o);}}p.pop();}let mut o=vec![];if dist.contains_key(&end){dfs(&end,&begin,&pre,&mut vec![],&mut o);}o}}
